enum Direction { Up , Down , Left , Right , } struct Vector2 { x : i32 , y : i32 , } impl Vector2 { fn move_in_dir (& self , dir : Direction , length : i32) -> Vector2 { match dir { Direction :: Up => { Vector2 { x : self . x , y : self . y - length } } Direction :: Down => { Vector2 { x : self . x , y : self . y + length } } Direction :: Left => { Vector2 { x : self . x - length , y : self . y } } Direction :: Right => { Vector2 { x : self . x + length , y : self . y } } } } } struct Model { block_pos : Vector2 , running : bool , } enum Msg { MoveBlock (Direction) , Quit } impl Model { fn update (& self , msg : Msg) -> Model { match msg { Msg :: MoveBlock (dir) => { Model { block_pos : self . block_pos . move_in_dir (dir , 1) , .. self . clone () } } Msg :: Quit => { Model { running : false , .. self . clone () } } } } }